-- Tarot Cards Seed Data
-- Generated from Manus DB

CREATE TABLE IF NOT EXISTS `tarot_cards` (
  `id` int NOT NULL,
  `name` varchar(50) NOT NULL,
  `positive_traits` text NOT NULL,
  `negative_traits` text NOT NULL,
  `meaning` text NOT NULL,
  `upright` text NOT NULL,
  `reversed` text NOT NULL,
  `script_analysis` text,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `positive_traits`=VALUES(`positive_traits`), `negative_traits`=VALUES(`negative_traits`), `meaning`=VALUES(`meaning`), `upright`=VALUES(`upright`), `reversed`=VALUES(`reversed`), `script_analysis`=VALUES(`script_analysis`);
