INSERT INTO `tarot_cards` (`id`, `name`, `positive_traits`, `negative_traits`, `meaning`, `upright`, `reversed`, `script_analysis`) VALUES
(0, '愚人', '憨厚耿直，做事誠懇，相信人性本善。樂觀開朗，有創意，沒有世俗框架。活在當下，享受生活，崇尚自由。不記仇，不會把難過的事情放在心上。', '容易被騙，耳根子軟。沒有危機意識，不計劃未來。時間觀與常人不同，記憶力差，容易翻舊帳的感覺。', '活在當下', '活在當下的喜樂感受，專注、不重世俗或他人看法', '沒活在當下，沒有專注，內心恐懼，無法處在當下', '不存在流年。資料明確指出，這個世代的人成年出社會後，不會遇到0的流年。因為「你就是那個愚人」，這張牌代表的是你的本質，而非流年運勢。'),
(1, '魔法師', '喜歡變化，活潑外向。反應快，聰明，能舉一反三。對事物充滿熱情，善於溝通，話題多。善於運用資源，能起死回生。樂意幫助朋友解決問題。', '外貌協會，以貌取人。善變，不喜歡待在同一個地方太久。情緒波動大，容易生氣，會記仇。', '與行動相關，強調開始行動', '無限創造力，行動立刻行動', '不要行動、無法行動', '不存在流年。魔術師通常只有透過「共振」或極為特殊的計算（如西元年拆開相加等於1）才會遇到，這在一般流年計算中不會直接出現。'),
(2, '女祭師', '重視精神生活，有靈性。聰明伶俐，學東西快。不喜歡起衝突，逆來順受。淡薄名利，是人與人之間的消波塊。有特殊體質。', '完美主義，龜毛。容易憂鬱，壓抑自己的情感。想多做少，計劃很多但執行很少。常常與世隔絕，吵架很弱。', '背離情感、情緒，不行動', '冷靜，只想不行動、想多做少、保持現況', '不冷靜、判斷力、是非不分、感情用事、口是心非', '主要為共振影響，通常不會直接遇到，而是透過流年11（正義）來共振。代表「獨立」、「冷靜」、「理智線斷裂」或「神秘學學習」。這段時間可能會感到孤單，或者被迫要靠自己，甚至會有情緒失控的狀況（因為壓力大）。'),
(3, '女皇', '有群眾魅力，天生帶有架勢。心胸寬大，有母愛。賺錢容易（選對行業），旺夫特質。容易拼到主管階級，有野心，不願意寄人籬下。', '自戀，喜歡征服，不喜歡送上門的追求者。金錢觀不好，賺得多花得也多。感情是人生重要功課，沒有愛就不能活。', '動之以情，講感受、感情很好', '女性貴人、豐盛豐收、吃的好', '女性的阻礙者、你不是他心中的女皇、太胖、太奢侈', '成年後罕見，主要透過流年12（吊人）共振。代表「豐收」、「懷孕」、「培育」。好的一面是被照顧或照顧人（如懷孕、提攜後輩）；壞的一面是變成「黃臉婆」或「老媽子」，需要幫人收拾善後。'),
(4, '國王', '行事果決，有領導才能。對事不對人，是就是，不是就不是。白手起家型，心臟大顆，堅強。喜歡先做再說，從經驗中學習。有危機意識，用生命去體驗，經驗值豐富。', '脾氣不好，一意孤行。不容易放下身段，自尊很強。吃軟不吃硬。有距離感，不喜歡人太靠近。', '講求制式、倲統、規矩，不苟言笑', '男性貴人，事業有成、真命天子，有擔當，有奠定穩固、基礎、循序漸進，制式、傳統、規矩', '男性阻礙者，沒擔當，沒地位，防備心強、剛愎自用', '主要透過流年13（死神）共振。代表「事業成就」、「建立王國」。若共振良好，是在死神年後重生的事業高峰；若為逆位，則是固執、不聽勸、或王國（事業/家庭）崩塌。'),
(5, '教宗', '很會聊天，會開話題。有品味，氣質不凡。重道德，有正義感。清心寡慾，追求心靈。適合做組織行銷，靠團隊。', '話匣子打開會聊到明天。沒什麼事業心（除非搭配世俗數字）。比較保守，愛說教。不喜歡世俗競爭，比較悲觀，先從壞的一面看。', '擇善固執，不好溝通，需要學習', '"貴人、老師（找到一個老師或是教學）、團隊、心靈成長，感情身心靈合一', '錯誤的團隊或貴人、不要靠別人、感情貌合神離。', '這一年通常是因為「有事」才會想心靈成長。會面臨「入世」（找到三觀一致的團隊/成為帶領者）或「出世」（覺得人很煩/遠離人群）的選擇。容易遇到貴人或神棍，取決於你的智慧。'),
(6, '戀人', '溫柔體貼，善解人意。心很細，注意到別人的需求。重感情，桃花旺。照顧者的角色，適合當看護。', '心腸太軟，借錢不用還。容易受傷，玻璃心。容易被愛沖昏頭，遇人不淑。感情用事，想不開。常為人際關係煩惱。', '不被干擾的方式就是不要理他', '人際關係（可能是開始，也可能是結束），認識新的朋友，和朋友見面、聊天、喝下午茶，約會、合作、結盟', '漸行漸遠、不結盟合作、地下情、友達以上戀人未滿，夫妻有名無實', '這是「建立新關係」或「結束舊關係」的一年。重點在於為明年的「戰車」做準備，需要對人好一點，累積人脈與資源。可能會遇到合作結盟，但也可能因為不是合格的戀人/夥伴而被切斷關係。'),
(7, '戰車', '有衝勁、魄力、膽識。理性，會想策略。決定要做就勇往直前。活潑，對朋友好。顧家，護短。適合做業務。', '情緒強烈，容易衝動，脾氣不好。比較容易被帶壞（青少年時期）。喜歡競爭。遇到衝擊會躲起來一段時間。晚上睡眠障礙，腦袋一直在轉，想太多。', '挑戰、戰場、戰鬥', '打拼（有利的挑戰）如果要簽約就選這一天，工作運好，要理性，有出差或旅行的意思', '容易戰敗、用錯方法，這不是你的戰場，交通易外', '這一年是事業衝刺期，不適合女生談戀愛（容易影響事業運）。你會找到一個有優勢的新戰場去打拼，累積經驗值。需特別注意車關（交通意外）或靈魂前往新戰場（意指離世，較極端情況）。'),
(8, '力量', '個性豪邁，以朋友為主。有義氣，超級好朋友。妒惡如仇，有正義感，會講道理。行動派，男生長得魁梧，很man。', '選擇困難症第一名。比較直接，頭腦簡單。講話容易得罪人，不夠圓融。想久了之後就不做了（與戰車相反）。', '決通解決問題，以柔克剛', '溝通、累、勞心勞力，但問題不會完全解決', '無效溝通，被問題拖著走，無法溝通，無力感', '感覺「煩躁」、「騷腦」，常有別人找麻煩（小官符：合約糾紛、詐騙、內耗）。這是修煉內在勇氣與柔性平衡的一年。男生適合「安太座」旺事業；女生若感情太順容易影響財運。'),
(9, '隱士', '有宗教緣，有智慧。看事情看得深，深謀遠慮。諸葛亮型，會給策略。會保守秘密，重內在。有特殊體質。', '不愛說話，內心孤獨，高處不勝寒。一直自我反省，思想複雜。個性壓抑，猶豫不決。看起來憂鬱、厭世。容易過敏。', '孤獨的老人、探索心靈成長，方向感，有經驗的人', '找方向、孤單、寂寞、冷、小人多、搞神秘、搞失蹤、低調', '沒方向、方向錯誤，獨自摸索', '會感到孤單、不被理解、找不到方向，甚至覺得小人很多。這是為了讓你「沉澱」以迎接明年的大運。建議主動去學習、讀書、將經驗分享給他人（成為引路的老人），而非封閉自己。'),
(10, '命運之輪', '漂亮、帥，有人緣。天之驕子/驕女，命帶富貴。助力多，遇到困難會有貴人。努力一分可以得到十分。自帶幸運星，容易發生好事。', '生命經驗值薄弱，不惜福，不珍惜。喜歡享受，沒有太大的受挫經驗。', '作一得二的好牌', '運氣好、好運、開心、時機到了，一種時機點的感受（搭火車，剛好火車誤點，搭上了）', '時間未到，逆勢而為', '感覺「時間到了」，會很想做些什麼（創業、結婚、離婚等）。資源會主動靠近，讓你過度樂觀。這是一把雙面刃，若德不配位（實力不足卻許大願），隔年（11）會摔得很慘。也是極少數人會遇到「生命時間到了」的關卡。'),
(11, '正義', '任勞任怨，鞠躬盡瘁，死而後已。經驗豐富（努力十次才獲得一次成功）。凡事投入，非常自律。', '努力十分，得一分。感覺一直在為別人而活。過於付出，個性壓抑，凡事自己扛。', '一分努力一分收獲，代表公平', '公平正義，認份、仲裁、衡量，合約、付出、簽約', '不公平、不道德、無法衡量', '命運之輪後的檢驗期。若前一年過太爽或實力不足，這一年會面臨巨大壓力、法律糾紛、合約問題或正義魔人的指點。解法是「咬牙扛下來」並「守護情緒」，付出的努力隔年會有收穫。'),
(12, '吊人', '逆向思維，有創意。適合創意職業、設計師。很會開話題，反應快，聰明，會舉一反三。會為大局著想，可以犧牲自己成全大家。有特殊體質。', '叛逆、怪胎、不聽話（在他人眼中）。聽不進勸。兩極化，犧牲時很犧牲，叛逆時很叛逆。', '束縛、犧牲、綁住、不同角度看世界', '收獲、犧牲、綁住', '不得已、不情願的被束縛、犧牲、綁住，行動受阻', '感覺動彈不得、不自由，像在還債或幫人擦屁股。若是正位，是「心甘情願」的犧牲（因為看到了願景）；若是逆位，則是「不情不願」的受苦。這是提升認知的最佳時刻，建議安在當下學習。'),
(13, '死神', '安靜，看問題看得深，有大智慧。探討事情很深入，洞悉生命、看透生命。一旦下定目標就咬得很死。自帶氣場。有宗教緣，有特殊體質。', '看著他的臉不知道在想什麼。陰沈和城府深（在世俗眼光中）。家庭功課重（晚婚、離婚、家人問題等）。命運多舛，比較坎坷。看起來孤獨，不喜歡跟別人攪和在一起。會往自己內化，不會把苦隨便跟別人講。沒有存在感（搭配某些數字時）。', '結束', '結束', '暫時無法結束、不願面對或放手結束，最後還是得結束', '靈魂課業最重的一年，沒有延畢機制。會經歷「痛」與「結束」來逼你領悟和蛻變（如分手、離職、生病）。建議有意識地自討苦吃（做高難度的改變或學習），主動斷捨離不適合的人事物，以完成流年當量。'),
(14, '節制', '很會算計，機關算盡。保守自制，知道自己要做什麼。重感情，不容易出軌。做事三思而後行，喜歡學習。', '放不開，不敢衝，安於現狀。握怕死、放怕飛，容易錯失投資時機。想太多，固執。博而不精。', '要控制、跨界、異交流', '做事要有限度、去學習、教學、出去玩、跨領域、跨區域、跨縣市', '適應不良、跨得不好、劈腿被抓', '死神過後的重生。必須跨出去（跨領域、跨國、跨專業）並進行交流（教與學），才能獲得財富與精神成長。是收穫世俗禮物的一年。'),
(15, '惡魔', '最會媚惑，蠱惑人心。擅長人際關係，號召力強。精力旺盛（尤其晚上），愛講話。有偏財運，可以投機。容易取得世俗成功。', '夜行性動物。天生有優越感，覺得自己高人一等。慾望強烈，不滿足。棄道德，比較沒有道德，利益擺在道德之前。容易忽略內在精神，過於流於物質。', '交換法則', '"慾望的展現，吃喝玩樂，想要談case也可以選這一天，跟事業相關的事，在這一天可能會遇到靠山"', '交換不起，沒有本錢交換被困住，不快樂', '世俗上的好牌，心靈上的壞牌。容易獲得金錢地位，但代價可能是健康、陪伴家人的時間或良心。會面臨酒色財氣的考驗，或被人情/道德綁架。切記不要拿壽命去換財富。'),
(16, '高塔', '聰明伶俐，有靈性。活潑，有長輩緣，人緣佳。個性獨立，長得漂亮，有親和力。朋友很多，三教九流都有。適合投資房地產。', '容易遲到。天生總有意外發生，容易有突發狀況，身不由己。生命容易受外力干擾。', '意外，生命的結束', '別人給你意外、生命的結束', '你給別人意外，拒絕你', '上天的懲罰，強制關機。會發生突如其來的變故（如裁員、意外、分手），打破原本的架構。但這其實是「包著爛包裝紙的禮物」，破壞後能讓你找到真正的新戰場（共振戰車）。建議多買保險。'),
(17, '星星', '長得有喜感，有靈性。領悟力高，對新東西（科技、網路）學得快。聰明，創造力、想像力強。低調。', '不愛說話，不喜歡表現。個性含蓄，三分鐘熱度，續航力不足，怕挫折。不好親近，有距離感。', '信心', '用自己的努力就一定有信心、有希望', '沒有希望、沒有信心、要暫緩', '在事業上升期容易被看見、有助力。但也可能代表「夢想豐滿，現實骨感」的落差壓力。對老年人或特定組合來說，可能有「隕落」（離世）的風險。'),
(18, '月亮', '浪漫、溫柔、重感情。相信理想可行，有浪漫情懷。直覺很強，適合做心理分析師、心理治療師。溫和，給人溫暖，在黑暗時刻帶給人希望。', '不切實際，愛幻想。比較愛哭，容易感情用事，容易感動。', '自己感到不安', '自己覺得不安，但情況還可控制，混沌不明，要居安思危', '關係破裂，不是現在能處理的情況，冷處理', '內心感到惶恐、敵友難分，覺得環境中有謊言或變數。老年人遇到此流年需注意身體健康的不安訊號。'),
(19, '太陽', '有領導能力，有人緣，有愛心。和善，充滿熱度。適合做公關人員或演藝人員。很快能把自己收拾好，不希望把不好的一面給別人看。樂觀，對事業有野心。', '熱情過度，可能讓人覺得太強勢。太為別人著想，比較固執。太過樂觀（在危險時可能不好）。會把負面情緒內化。', '光明、快樂', '光明、開心、天氣很好，遇到有童真的孩子或人', '美中不足，有遺憾', '通常年輕人不易直接遇到（多為共振）。老年人遇到可能代表「返老還童」（赤子之心或失智/退化成小孩），需要像孩子一樣被照顧。'),
(20, '審判', '霸氣，心臟很強。完美主義，非常自律，有自我管理能力。適合當職業軍人、教官、審查者。一板一眼。從商或從政能力強（男性）。', '會一直審判別人，從雞蛋裡挑骨頭。有強烈的自我優越意識，斤斤計較。主觀意識很強，只要求別人。女性命苦，太強太能忍。', '得到消息、提升', '有人來找（認識的人），得到訊息，因果業力引爆，看到別人辦喪事，有所提升', '沒有消息、不好的消息、無法提升', '清算的時刻。認識你的人（包含看不見的）都會來找你。做好事上天堂，做壞事下地獄。老年人遇到可能代表受到召喚（壽命議題）。'),
(21, '世界', '天生豁達，凡事看得開。不受拘束，心胸寬大，有包容力。樂觀，適合當社工，可以傾聽別人心事。', '不在乎金錢（或很在乎但喜歡花）。喜歡輕鬆生活，不喜歡被綁。太過豁達，什麼都算了，不追求，不想辛苦。隨心所欲，喜歡獨行天涯。太飄，生活不穩定。', '圓滿完成', '圓滿完成、出去玩，一種心境上的壑達', '不圓滿、沒有完成你的功課或學習、無法脫離或出去玩。', '檢視靈魂學習是否圓滿。透過「同質」（業力爆發）與「異質」（看不順眼的人）來提醒你學會彈性與平衡。老年人遇到通常代表旅程結束（投胎轉世）。')
